"""matplotlib.backends.backend_gtk4cairo — gtk4cairo backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_gtk4cairo import
FigureCanvasGTK4Cairo`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasGTK4Cairo = _make_canvas('FigureCanvasGTK4Cairo', 'png')
FigureManagerGTK4Cairo = _make_manager('FigureManagerGTK4Cairo')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasGTK4Cairo
FigureManager = FigureManagerGTK4Cairo

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendGTK4Cairo', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show
